/**
 * Read-only PostgreSQL probes for Odoo databases: installed modules and
 * Odoo series detection via the base module version.
 */
import { execFile } from 'node:child_process';
import * as util from 'node:util';
import { InstalledModuleInfo } from '../models/module';
import { runtimeCache, invalidateInstalledModulesCache } from './runtimeCache';
import { logger } from './logger';

const execFileAsync = util.promisify(execFile);

const INSTALLED_MODULES_QUERY = `
    SELECT id, name, shortdesc, latest_version, state, application
    FROM ir_module_module
    WHERE state IN ('installed', 'to upgrade')
    ORDER BY name;
`.trim();

const INSTALLED_MODULE_NAMES_QUERY = `
    SELECT name
    FROM ir_module_module
    WHERE state IN ('installed', 'to upgrade')
    ORDER BY name;
`.trim();

const TABLE_EXISTS_QUERY = `
    SELECT EXISTS (
        SELECT FROM information_schema.tables
        WHERE table_name = 'ir_module_module'
    );
`.trim();

const ACTIVE_DATABASES_QUERY = `
    SELECT datname
    FROM pg_stat_activity
    WHERE datname IS NOT NULL
    GROUP BY datname;
`.trim();

const BASE_MODULE_VERSION_QUERY = `
    SELECT latest_version
    FROM ir_module_module
    WHERE name = 'base';
`.trim();

function validateDatabaseName(dbName: string): void {
    // Basic sanity check to avoid shell injection when invoking psql
    if (!/^[\w\-.:]+$/.test(dbName)) {
        throw new Error(`Invalid database identifier: ${dbName}`);
    }
}

async function runPsqlQuery(dbName: string, query: string, fieldSeparator = '|'): Promise<string> {
    validateDatabaseName(dbName);
    try {
        const args = [
            '--no-psqlrc',
            '--no-align',
            '--tuples-only',
            '-F',
            fieldSeparator,
            '-d',
            dbName,
            '-c',
            query
        ];

        const { stdout } = await execFileAsync('psql', args, {
            encoding: 'utf-8',
            maxBuffer: 10 * 1024 * 1024 // Allow reasonably large result sets
        });
        return stdout.trim();
    } catch (error) {
        logger.warn(`psql command failed for database "${dbName}":`, error);
        throw error;
    }
}

export async function databaseHasModuleTable(dbName: string): Promise<boolean> {
    try {
        const result = await runPsqlQuery(dbName, TABLE_EXISTS_QUERY);
        return result === 't';
    } catch {
        return false;
    }
}

export async function getInstalledModules(dbName: string): Promise<InstalledModuleInfo[]> {
    return runtimeCache.getInstalledModules(dbName, async () => {
        const modules: InstalledModuleInfo[] = [];

        if (!(await databaseHasModuleTable(dbName))) {
            logger.debug(`Database ${dbName} does not contain Odoo tables yet.`);
            return modules;
        }

        let output: string;
        try {
            output = await runPsqlQuery(dbName, INSTALLED_MODULES_QUERY);
        } catch (error) {
            logger.warn(`Failed to fetch installed modules for database "${dbName}":`, error);
            return modules;
        }

        if (!output) {
            return modules;
        }

        for (const line of output.split('\n').map(entry => entry.trim()).filter(Boolean)) {
            const [id, name, shortdesc, latestVersion, state, application] = line.split('|');

            let description = shortdesc || '';
            if (shortdesc) {
                try {
                    const parsed = JSON.parse(shortdesc);
                    const locales = Object.keys(parsed);
                    if (locales.length > 0) {
                        description = parsed.en_US ?? parsed[locales[0]] ?? '';
                    }
                } catch {
                    // Keep original string when JSON parsing fails
                    description = shortdesc;
                }
            }

            modules.push({
                id: Number.parseInt(id ?? '', 10),
                name: name ?? '',
                shortdesc: description ?? '',
                installed_version: latestVersion || null,
                latest_version: latestVersion || null,
                state: state ?? '',
                application: application === 't'
            });
        }

        return modules;
    });
}

export async function getInstalledModuleNames(dbName: string): Promise<Set<string>> {
    const names = await runtimeCache.getInstalledModuleNames(dbName, async () => {
        if (!(await databaseHasModuleTable(dbName))) {
            return [];
        }

        let output: string;
        try {
            output = await runPsqlQuery(dbName, INSTALLED_MODULE_NAMES_QUERY);
        } catch (error) {
            logger.warn(`Failed to fetch installed module names for database "${dbName}":`, error);
            return [];
        }

        if (!output) {
            return [];
        }

        return output
            .split('\n')
            .map(entry => entry.trim())
            .filter(Boolean);
    });

    return new Set(names);
}

export function clearInstalledModuleCache(dbName?: string): void {
    invalidateInstalledModulesCache(dbName);
}

/**
 * Extracts the Odoo series (branch name) from a base module version string:
 * "17.0.1.3" -> "17.0", "saas~17.4.1.2" -> "saas-17.4".
 */
export function parseOdooSeries(baseModuleVersion: string | undefined | null): string | undefined {
    if (!baseModuleVersion) {
        return undefined;
    }
    const match = /^(saas[~-])?(\d+)\.(\d+)/.exec(baseModuleVersion.trim());
    if (!match) {
        return undefined;
    }
    const series = `${match[2]}.${match[3]}`;
    return match[1] ? `saas-${series}` : series;
}

/**
 * Detects which Odoo series (e.g. "17.0", "saas-17.4") a database runs by
 * reading the base module's version. Best-effort: returns undefined for
 * non-Odoo databases or when psql is unavailable.
 */
export async function detectOdooSeries(dbName: string): Promise<string | undefined> {
    try {
        if (!(await databaseHasModuleTable(dbName))) {
            return undefined;
        }
        const output = await runPsqlQuery(dbName, BASE_MODULE_VERSION_QUERY);
        return parseOdooSeries(output);
    } catch (error) {
        logger.warn(`Failed to detect Odoo series for database "${dbName}":`, error);
        return undefined;
    }
}

export function parseActiveDatabaseNames(output: string): string[] {
    return output
        .split('\n')
        .map(entry => entry.trim())
        .filter(Boolean);
}

/**
 * Databases with at least one live backend, which catches servers started
 * from a terminal or another window - not just the ones this extension
 * launched. Queried through the `postgres` maintenance database because the
 * view is cluster-wide. Best-effort: an unreachable cluster reports nothing.
 */
export async function getActiveDatabaseNames(): Promise<string[]> {
    return runtimeCache.getActiveDatabases(async () => {
        try {
            return parseActiveDatabaseNames(await runPsqlQuery('postgres', ACTIVE_DATABASES_QUERY));
        } catch (error) {
            logger.debug('Could not read active databases from pg_stat_activity:', error);
            return [];
        }
    });
}
